[$['data']['slides'][0]['description']['original']] <div class="banner-main banner-main-myameria banner-main-um">
    <div class="container">
        <div class="row">

            <div class="banner-main__body">
                <div class="banner-main-um__info">
                    <div class="banner-main-um__tablet-bg"></div>
                    <img src="https://ameriabank.am/Portals/0/Images/consumer-finance/consumer-finance-mobile.png" class="banner-main-um__img-mobile" style="width: 100% !important;" alt="banner">
                    <div class="banner-main__content banner-main__content--white">
                        <h1 class="banner-main__title">Consumer finance
                        <p class="banner-main__description paragraph-large">Installment loans at the points of sale will make <br>your shopping experience quick and hassle-free
                        <div class="banner-main__content-footer">
                            <a id="banner-btn" class="button button_secondary" style="cursor: pointer;">See list of partners</a>
                        </div>
                    </div>
                </div>
            </div>

        </div>
    </div>
</div>
<style>
    #slider .slide.wsc-no-overlay.background-image.wsc-static,
    .banner-main-um__tablet-bg {
        background-image: url("https://ameriabank.am/Portals/0/Images/consumer-finance/consumer-finance-web.png") !important;
    }
    .inspiro-slider .slide,
    .inspiro-slider .owl-stage {
        height: 700px !important;
    }
    .banner-main-myameria .button {
        width: auto;
        border-radius: 14px;
    }
    .banner-main-myameria .banner-main__content h1 {
        font-size: 62px !important;
        line-height: 72px !important;
    }
    .banner-main-myameria .banner-main__content-footer {
        margin-bottom: 40px;
    }
    .owl-carousel.dots-creative .owl-dots {
        bottom: 72px;
    }
    .banner-main__description {
        color: #fff !important;
    }
    .btn-tooltip-banner > a {
        display: flex;
        align-items: center;
        gap: 8px;
    }
    .btn-join-mobile {
        display: none !important;
    }
    .banner-main__title {
        color: #fff !important;
    }
    .banner-main-um__info {
        width: 100%;
    }
    .banner-main-um__img-mobile {
        display: none !important;
    }
    .banner-main-um__tablet-bg {
        display: none;
    }
    @media screen and (max-width: 1400px) {  
        #slider .slide.wsc-no-overlay.background-image.wsc-static {
            background-position: 90%;
        }
    }
    @media screen and (max-width: 1200px) {  
        .owl-carousel.dots-creative .owl-dots {
            bottom: 7px;
        }
    }
    @media screen and (max-width: 992px) {  
        .banner-main-myameria .banner-main__content, 
        .banner-main-myameria .banner-main__media {
            width: auto;
        }
        #slider .slide.wsc-no-overlay.background-image.wsc-static {
            background-position: 80%;
        }
        .btn-tooltip-banner {
            display: none;
        }
        .btn-join-mobile {
            display: inline-block !important;
        }
    }
    @media screen and (max-width: 768px) { 
        .banner-main > .container {
            padding: 0;
        }
        .banner-main__body {
            align-items: flex-end;
        }
        .banner-main__content {
            display: flex;
            flex-direction: column;
            padding: 20px 16px;
            background-color: #404040;
        }
        .banner-main__content--white {
            background-color: #fff;
        }
        .banner-main__content--white .banner-main__title,
        .banner-main__content--white .banner-main__description  {
            color: #171717 !important;
        }
        .banner-main-myameria .banner-main__content-footer {
            margin-bottom: 28px;
        }
        .banner-main__content-footer .button {
            margin-bottom: 0;
        }
        #slider .slide.wsc-no-overlay.background-image.wsc-static {
            background-image: none !important;
        }
        .banner-main-um__tablet-bg {
            display: block;
            background-repeat: no-repeat;
            background-size: cover;
            width: 100%;
            height: 560px;
            background-position: 95% 0%;
        }
        .inspiro-slider {
            background-color: #fff !important;
        }
    }
    @media screen and (max-width: 576px) {  
        .banner-main {
            margin: 0 -5px;
        }
        .banner-main__body {
            flex-direction: initial;
            padding: 0;
        }
        .banner-main__title {
            margin-bottom: 8px !important;
            text-align: center;
        }
        .banner-main-myameria .banner-main__media {
            padding: 0;
        }
        .banner-main-myameria .banner-main__content {
            width: 100%;
        }
        .banner-main-myameria .banner-main__content h1 {
            font-size: 36px !important;
            line-height: 46px !important;
            word-break: break-word;
        }
        .banner-main-myameria .banner-main__content-footer {
            flex-direction: column;
            gap: 8px;
            margin-bottom: 16px;
        }
        .banner-main-myameria .button {
            width: 100%;
        }
        .banner-main-myameria .button:first-of-type {
            margin-bottom: 0;
        }
        .banner-main__description {
            font-size: 16px !important;
            margin-bottom: 16px !important;
            text-align: center;
        }
        #slider .slide.wsc-no-overlay.background-image.wsc-static > .container,
        #slider .slide.wsc-no-overlay.background-image.wsc-static .slide-captions,
        #slider .wsc-static > .container,
        #slider .wsc-static > .container .slide-captions,
        .banner-main-myameria,
        .banner-main-myameria > .container,
        .banner-main-myameria > .container > .row,
        .banner-main__body {
            height: 100%;
        }
        .banner-main-um__tablet-bg {
            display: none;
        }
        .banner-main-um__img-mobile {
            display: inline-block !important;
        }
        .inspiro-slider .slide {
            height: auto !important;
        }
    }
</style>
<script>
    $("#banner-btn").click(function() {
        $([document.documentElement, document.body]).animate({
            scrollTop: $("#partner-companies-title").offset().top - 80
        }, 1500);
    });
</script>
